    let alive = true
    const finish = () => { if (!alive || doneRef.current) return; doneRef.current = true; onDone() }
    const tick = (_now, metadata) => {
      if (!alive) return
      const mediaTime = finite(metadata?.mediaTime) ? metadata.mediaTime : node.currentTime
      onFrame({ mediaTime, beamRect: node.getBoundingClientRect(), sourceWidth: node.videoWidth || BEAM_CALIBRATION.sourceWidth, sourceHeight: node.videoHeight || BEAM_CALIBRATION.sourceHeight })
      frameRef.current = node.requestVideoFrameCallback ? node.requestVideoFrameCallback(tick) : globalThis.requestAnimationFrame?.(tick)
    }
    frameRef.current = node.requestVideoFrameCallback ? node.requestVideoFrameCallback(tick) : globalThis.requestAnimationFrame?.(tick)
    node.addEventListener('ended', finish)
    node.addEventListener('error', finish)
    try { node.currentTime = 0; node.play()?.catch?.(finish) } catch { finish() }
