// Confetti in each character's own palette, so the celebration matches the pug on screen.
export const CONFETTI_COLORS = Object.freeze({ regular: ['#d9b48f', '#8a5a3b', '#f2dcc2', '#3a2a22'], banana: ['#ffe066', '#f5c518', '#fff3b0', '#7a5c12'], strawberry: ['#e63950', '#ff8fa3', '#4caf50', '#ffd1dc'], bonnet: ['#d4a24c', '#f5f1ea', '#b07a2a', '#f7c9a8'], cream: ['#f3d9c0', '#e8b89a', '#fff4e8', '#f4a7a3'], fold: ['#c9a888', '#f2e6d8', '#8a6a50', '#f4b6b0'], bow: ['#f5c518', '#ffe27a', '#9a8670', '#f4f1ec'] })
const CONFETTI = [[-30, 0, 0], [-12, 1, 0.1], [8, 2, 0.05], [26, 3, 0.15], [-22, 1, 0.25], [16, 0, 0.3], [0, 3, 0.2], [34, 2, 0.35]]
// Every character is drawn at the same STANDING height: each clip's median body height (measured
// from its frames) is scaled to FIT_TARGET of the companion box, feet on the box's bottom edge,
// body centred. Jumps and raised arms may briefly reach past the top, as a real dance would.
export const FIT_TARGET = 0.9
export const CHARACTER_FIT = Object.freeze({"banana": {"aspect": 0.75, "medH": 0.9437, "medBottom": 0.9625, "medCx": 0.4972}, "bonnet": {"aspect": 0.875, "medH": 0.8403, "medBottom": 0.9792, "medCx": 0.4821}, "bow": {"aspect": 0.8542, "medH": 0.7882, "medBottom": 0.9792, "medCx": 0.5234}, "cream": {"aspect": 0.7083, "medH": 0.934, "medBottom": 0.9792, "medCx": 0.5441}, "fold": {"aspect": 0.8819, "medH": 0.8819, "medBottom": 0.9653, "medCx": 0.4764}, "regular": {"aspect": 0.75, "medH": 0.9625, "medBottom": 0.9812, "medCx": 0.4917}, "strawberry": {"aspect": 0.75, "medH": 0.9604, "medBottom": 0.9771, "medCx": 0.475}})
export function characterVideoStyle(name) {
  const f = CHARACTER_FIT[name] || CHARACTER_FIT.regular
  const scale = FIT_TARGET / f.medH            // video height as a multiple of the box height
  const width = f.aspect * scale
  return { position: 'absolute', height: `${(scale * 100).toFixed(2)}%`, width: `${(width * 100).toFixed(2)}%`, top: `${((1 - f.medBottom * scale) * 100).toFixed(2)}%`, left: `${((0.5 - f.medCx * width) * 100).toFixed(2)}%`, objectFit: 'fill', maxWidth: 'none' }
}

export const BUBBLE_WORD = Object.freeze({ needs: 'NEED YOU!', done: 'DONE!', stuck: 'STUCK?' })
export const POW_INK = Object.freeze({ regular: '#8a5a3b', banana: '#7a5c12', strawberry: '#e63950', bonnet: '#b07a2a', cream: '#d9826b', fold: '#8a6a50', bow: '#c99a06' })

function Companion({ phase, prefs, position, dancing, mood, motionOff, onBeamDone, onOpenSettings, onTap, onCallout, drag, settingsOpen, showBubble }) {
  const calloutDown = useRef(false)
  const maskRef = useRef(null)
  const videoRef = useRef(null)
  const [ready, setReady] = useState(false)
  const direction = phase === 'arriving' ? 'down' : phase === 'departing' ? 'up' : null
  const zoom = cssZoomFactor()
  const size = clampSize(prefs.size) / zoom

  // Mask is owned imperatively during an effect and reset to fully visible otherwise.
  useLayoutEffect(() => {
    const node = maskRef.current
    if (!node) return
    node.style.maskImage = direction === 'down' ? MASK_HIDDEN : 'none'
    node.style.webkitMaskImage = node.style.maskImage
  }, [direction])

  useEffect(() => { setReady(false) }, [prefs.character])

  useEffect(() => {
    const video = videoRef.current
    if (!video || !ready) return
    video.playbackRate = mood?.kind === 'stuck' ? 0.5 : 1
    if (dancing) video.play()?.catch?.(() => {})
    else { video.pause(); try { video.currentTime = 0 } catch {} }
  }, [dancing, ready, prefs.character, mood?.kind])

  const onFrame = reading => {
    const node = maskRef.current
    if (!node || !direction || !reading?.beamRect) return
    const rect = node.getBoundingClientRect()
    const mapped = mapBeamEdge(direction, reading.mediaTime, reading.beamRect, rect, reading.sourceWidth, reading.sourceHeight)
    node.style.maskImage = maskForBeam(direction, mapped.edgePercent, rect.height)
    node.style.webkitMaskImage = node.style.maskImage
    node.dataset.puginEdge = mapped.edgePercent.toFixed(1)
  }

  if (phase === 'absent') return null
  const settled = phase === 'present'
  const moodKind = settled ? mood?.kind : null
  const bodyClass = `pugin-body${moodKind && !motionOff ? ` pugin-body--${moodKind}` : moodKind === 'stuck' ? ' pugin-body--stuck' : ''}`
  return jsx('div', {
    popover: 'manual',
    ref: node => { if (node && !node.matches?.(':popover-open')) { try { node.showPopover?.() } catch {} } },
    'data-pugin-sprite': phase,
    'data-pugin-mood': moodKind || 'none',
    style: { ...style.shell, left: position.x / zoom, top: position.y / zoom, pointerEvents: settingsOpen ? 'none' : 'auto', '--pugin-size': `${size}px` },
    children: jsxs('button', {
      type: 'button', style: style.button, 'aria-label': `PUGin ${prefs.character} companion${moodKind ? ` — ${mood.text}` : ''}. Click for this chat's work, drag to move, context menu for settings`,
      onClick: event => { const hit = calloutDown.current || Boolean(event.target?.closest?.('[data-pugin-bubble]')); calloutDown.current = false; if (hit && mood?.target) onCallout(mood.target); else onTap() },
      onContextMenu: event => { event.preventDefault(); onOpenSettings(event.currentTarget) },
      onPointerDown: event => { if (event.button !== 0) return; calloutDown.current = Boolean(event.target?.closest?.('[data-pugin-bubble]')); if (calloutDown.current) return; event.currentTarget.setPointerCapture?.(event.pointerId); drag.begin(event.clientX, event.clientY) },
      onPointerMove: event => drag.move(event.clientX, event.clientY),
      onPointerUp: () => drag.end(),
      onPointerCancel: () => drag.cancel(),
      onKeyDown: event => {
        const step = { ArrowLeft: [-1, 0], ArrowRight: [1, 0], ArrowUp: [0, -1], ArrowDown: [0, 1] }[event.key]
        if (step) { event.preventDefault(); drag.nudge(step[0], step[1], event.shiftKey) }
        else if (event.key === 'ContextMenu' || (event.key === 'F10' && event.shiftKey)) { event.preventDefault(); onOpenSettings(event.currentTarget) }
      },
      children: [
        jsx('span', { className: bodyClass, children: jsx('span', { ref: maskRef, 'data-pugin-mask': direction || 'none', style: { ...style.mask, opacity: clampOpacity(prefs.opacity) / 100 }, children: jsx('video', { key: prefs.character, ref: videoRef, src: ASSETS[prefs.character].dance, muted: true, loop: true, playsInline: true, preload: 'auto', onLoadedData: () => { try { videoRef.current.pause(); videoRef.current.currentTime = 0 } catch {} setReady(true) }, style: { ...characterVideoStyle(prefs.character), display: 'block', opacity: ready ? 1 : 0 } }) }) }),
        moodKind === 'done' && !motionOff ? CONFETTI.map(([dx, shade, delay], i) => jsx('span', { className: 'pugin-confetti', 'aria-hidden': true, style: { left: `${50 + dx}%`, background: (CONFETTI_COLORS[prefs.character] || CONFETTI_COLORS.regular)[shade], animationDelay: `${delay}s`, '--dx': `${dx}px` } }, i)) : null,
        moodKind === 'done' && showBubble ? jsxs('span', { className: 'pugin-pow', role: 'status', 'aria-live': 'polite', 'data-pugin-bubble': 'done', 'aria-label': mood.text, title: mood.text, children: [jsx('span', { className: 'pugin-pow__ink' }, 'i'), jsx('span', { className: 'pugin-pow__fill' }, 'f'), jsx('span', { className: 'pugin-pow__word', style: { color: POW_INK[prefs.character] || POW_INK.regular }, children: 'DONE!' }, 'w')] }) : null,
        moodKind && moodKind !== 'done' && showBubble ? jsxs('span', { className: `pugin-say pugin-say--${moodKind}`, role: 'status', 'aria-live': 'polite', 'data-pugin-bubble': moodKind, 'aria-label': mood.text, title: mood.text, children: [
          jsx('span', { className: 'pugin-say__box', children: BUBBLE_WORD[moodKind] }, 'b'),
          moodKind === 'stuck' ? jsx('span', { className: 'pugin-say__dot', style: { right: '22%', bottom: '-0.55em', width: '0.55em', height: '0.55em' } }, 'd1') : null,
          moodKind === 'stuck' ? jsx('span', { className: 'pugin-say__dot', style: { right: '12%', bottom: '-1.15em', width: '0.32em', height: '0.32em' } }, 'd2') : null
        ] }) : null,
        direction ? jsx(BeamEffect, { key: phase, direction, onFrame, onDone: onBeamDone }) : null
      ]
    })
  })
}

// Work receipt: what this chat has going, with elapsed time and stop / open / dismiss.
export function Receipt({ open, onClose, anchor, size, viewport, busy, linked, fresh, needs, stuck, onStop, onOpenKanban, onAnswer, onDismiss, focus = null, now = Date.now() }) {
  const [confirming, setConfirming] = useState(null)
  const [errors, setErrors] = useState({})
  const panelRef = useRef(null)
  useEffect(() => {
    if (!open) return undefined
    const onKey = event => { if (event.key === 'Escape') onClose() }
    const onDown = event => { if (panelRef.current && !panelRef.current.contains(event.target) && !event.target?.closest?.('[data-pugin-sprite]')) onClose() }
    globalThis.addEventListener?.('keydown', onKey)
    globalThis.document?.addEventListener?.('pointerdown', onDown, true)
    return () => { globalThis.removeEventListener?.('keydown', onKey); globalThis.document?.removeEventListener?.('pointerdown', onDown, true) }
  }, [open]) // eslint-disable-line react-hooks/exhaustive-deps
  if (!open) return null
  const zoom = cssZoomFactor()
  const view = viewportSnapshot(viewport)
  const sprite = clampSize(size)
  const above = anchor.y > 280
  const box = { position: 'fixed', inset: 'auto', margin: 0, zIndex: 1001, width: 290, maxWidth: 'calc(100vw - 16px)', maxHeight: 360, overflowY: 'auto', boxSizing: 'border-box', padding: 10, borderRadius: 10, font: '12px/1.4 system-ui,sans-serif', color: 'var(--ui-text-primary, #f4f4f5)', background: 'var(--ui-bg-elevated, #1c1c21)', border: '1px solid var(--ui-stroke-secondary, #3f3f46)', boxShadow: '0 8px 24px rgba(0,0,0,.3)', right: Math.max(8, view.width - (anchor.x + sprite)) / zoom, ...(above ? { bottom: (view.height - anchor.y + 8) / zoom } : { top: (anchor.y + sprite + 8) / zoom }) }
  const btn = { padding: '2px 8px', borderRadius: 6, border: '1px solid var(--ui-stroke-secondary, #3f3f46)', background: 'transparent', color: 'inherit', cursor: 'pointer', fontSize: 11 }
  const stuckIds = new Set(stuck.map(item => `${item.kind}:${item.id}`))
  const row = (item, extra = [], key) => jsxs('div', { 'data-pugin-receipt-item': item.kind, 'data-pugin-focus': focus && focus === `${item.kind}:${item.id}` ? true : undefined, style: { display: 'flex', gap: 6, alignItems: 'flex-start', padding: '5px 0', borderTop: '1px solid var(--ui-stroke-secondary, #3f3f46)' }, children: [
    jsx('span', { 'aria-hidden': true, children: KIND_ICON[item.kind] || '•' }),
    jsxs('div', { style: { flex: 1, minWidth: 0 }, children: [
      jsx('div', { style: { overflowWrap: 'anywhere' }, children: item.label }),
      item.detail ? jsx('div', { style: { color: 'var(--ui-text-secondary, #a1a1aa)', fontSize: 11 }, children: item.detail }) : null,
      errors[key] ? jsx('div', { style: { color: '#ef4444', fontSize: 11 }, children: errors[key] }) : null
    ] }),
    jsx('div', { style: { display: 'flex', gap: 4, flexShrink: 0 }, children: extra })
  ] }, key)
  const stopButton = item => {
    const key = `${item.kind}:${item.id}`
    if (!item.id) return null
    return jsx('button', { type: 'button', style: { ...btn, ...(confirming === key ? { borderColor: '#ef4444', color: '#ef4444' } : {}) }, onClick: async () => {
      if (confirming !== key) { setConfirming(key); return }
      setConfirming(null)
      const result = await onStop(item)
      setErrors(current => ({ ...current, [key]: result?.error ? `Couldn't stop: ${result.error}` : '' }))
    }, children: confirming === key ? 'Confirm stop' : 'Stop' }, 'stop')
  }
  const openButton = item => jsx('button', { type: 'button', style: btn, onClick: () => onOpenKanban(item), title: `Open Kanban (copies ${item.id})`, children: 'Open' }, 'open')
  const sections = []
  if (needs.length) sections.push(jsx('div', { style: { fontWeight: 600, marginTop: 6 }, children: 'Needs you' }, 'h-needs'), ...needs.map(item => item.kind === 'approval'
    ? row({ ...item, detail: 'Waiting for your answer in this chat' }, [jsx('button', { type: 'button', style: btn, onClick: onAnswer, children: 'Answer' }, 'answer')], `n-${item.id}`)
    : row({ ...item, detail: item.reason || 'Blocked' }, [openButton(item), jsx('button', { type: 'button', style: btn, onClick: () => onDismiss(item.id), children: 'Dismiss' }, 'dismiss')], `n-${item.id}`)))
  const running = []
  if (busy) running.push(row({ kind: 'chat', label: 'This chat is responding' }, [], 'chat'))
  if (fresh) {
    for (const item of linked.subagents) running.push(row({ ...item, detail: [formatElapsed(item.startedAt ? now - item.startedAt : NaN), item.lastTool, stuckIds.has(`subagent:${item.id}`) ? '😟 might be stuck' : ''].filter(Boolean).join(' · ') }, [stopButton(item)], `s-${item.id}`))
    for (const item of linked.processes) running.push(row({ ...item, detail: formatElapsed(item.startedAt ? now - item.startedAt : NaN) }, [stopButton(item)], `p-${item.id}`))
    for (const item of linked.kanban) running.push(row({ ...item, detail: [formatElapsed(item.startedAt ? now - item.startedAt : NaN), item.board, stuck.find(s => s.kind === 'kanban' && s.id === item.id)?.why ? `😟 ${stuck.find(s => s.kind === 'kanban' && s.id === item.id).why}` : ''].filter(Boolean).join(' · ') }, [openButton(item)], `k-${item.id}`))
  }
  sections.push(jsx('div', { style: { fontWeight: 600, marginTop: 6 }, children: 'Running' }, 'h-run'), ...(running.length ? running : [jsx('div', { style: { color: 'var(--ui-text-secondary, #a1a1aa)', padding: '4px 0' }, children: fresh || busy ? 'Nothing running for this chat.' : 'Checking…' }, 'none')]))
  const done = fresh ? linked.recentDone.slice(-3).reverse() : []
  if (done.length) sections.push(jsx('div', { style: { fontWeight: 600, marginTop: 6 }, children: 'Recently finished' }, 'h-done'), ...done.map(item => row({ ...item, kind: 'kanban', detail: [item.completedAt ? `${formatElapsed(now - item.completedAt)} ago` : '', item.result].filter(Boolean).join(' · ') }, [], `d-${item.id}`)))
  if (fresh && linked.kanbanQueued) sections.push(jsx('div', { style: { color: 'var(--ui-text-secondary, #a1a1aa)', marginTop: 6 }, children: `${linked.kanbanQueued} Kanban card${linked.kanbanQueued > 1 ? 's' : ''} queued` }, 'queued'))
  return jsx('div', {
    popover: 'manual', ref: node => { panelRef.current = node; if (node && !node.matches?.(':popover-open')) { try { node.showPopover?.() } catch {} } },
    role: 'dialog', 'aria-label': "This chat's work", className: 'pugin-receipt', 'data-pugin-receipt': true, style: box,
    children: [
      jsxs('div', { style: { display: 'flex', justifyContent: 'space-between', alignItems: 'center' }, children: [jsx('strong', { children: "This chat's work" }), jsx('button', { type: 'button', style: btn, onClick: onClose, 'aria-label': 'Close', children: '✕' })] }, 'head'),
      ...sections
    ]
  })
}

export function StatusPanel({ activity, linked, prefs, phase, busy, motionReason, needs = [], stuck = [] }) {
  const lines = []
  lines.push(busy ? 'This chat: responding' : 'This chat: idle')
  if (prefs.danceScope === 'chat-linked') {
    if (!linked) lines.push('Linked work: checking…')
    else {
      for (const item of activity.reasons.filter(r => r.kind !== 'chat')) lines.push(`${item.kind === 'subagent' ? 'Subagent' : item.kind === 'process' ? 'Process' : 'Kanban'}: ${item.label}`)
      if (activity.linkedFresh && !activity.reasons.some(r => r.kind !== 'chat')) lines.push('Linked work: none running')
      for (const item of needs) lines.push(`Needs you: ${item.label}`)
      for (const item of stuck) lines.push(`Might be stuck: ${item.label} (${item.why})`)
      if (linked.kanbanQueued > 0) lines.push(`Kanban queued (not counted): ${linked.kanbanQueued}`)
      for (const note of linked.notes) lines.push(note)
    }
  }
  if (motionReason) lines.push(motionReason)
  lines.push(`Companion: ${phase}${prefs.hidden ? ' (hidden)' : ''}`)
  const counts = { subagent: 0, process: 0, kanban: 0 }
  for (const item of activity.reasons) if (item.kind in counts) counts[item.kind] += 1
  const parts = [busy ? 'chat responding' : null, counts.subagent ? `${counts.subagent} subagent${counts.subagent > 1 ? 's' : ''}` : null, counts.process ? `${counts.process} process${counts.process > 1 ? 'es' : ''}` : null, counts.kanban ? `${counts.kanban} Kanban` : null].filter(Boolean)
  const tone = needs.length ? 'needs' : activity.working ? 'working' : 'idle'
  const summary = needs.length ? `Needs you (${needs.length})` : activity.working ? `Working — ${parts.join(', ')}` : 'Idle'
  const flag = linked?.notes?.length ? ' ⚠' : ''
  return jsxs('details', { className: 'pugin-set__status', 'data-pugin-status': true, children: [
    jsxs('summary', { children: [jsx('span', { className: `pugin-set__dot pugin-set__dot--${tone}`, 'aria-hidden': true }, 'd'), jsx('span', { children: `Status: ${summary}${flag}` }, 't')] }),
    jsx('div', { role: 'status', 'aria-live': 'polite', className: 'pugin-set__status-lines', children: lines.map((line, i) => jsx('div', { children: line }, i)) })
  ] })
}

