function Segmented({ label, value, options, onChange }) {
  return jsx('div', { className: 'pugin-set__seg', role: 'radiogroup', 'aria-label': label, children: options.map(([key, text]) => jsx('button', { type: 'button', role: 'radio', 'aria-checked': value === key, onClick: () => onChange(key), children: text }, key)) })
}

function Slider({ label, value, min, max, unit, onChange }) {
  return jsxs('label', { className: 'pugin-set__slider', children: [jsx('span', { children: label }, 'l'), jsx('input', { type: 'range', min, max, value, onChange: e => onChange(e.target.valueAsNumber), 'aria-label': label }, 'i'), jsx('span', { className: 'pugin-set__val', children: `${value}${unit}` }, 'v')] })
}

export function CharacterPicker({ value, onChange }) {
  const onKeyDown = event => {
    const step = { ArrowRight: 1, ArrowDown: 4, ArrowLeft: -1, ArrowUp: -4 }[event.key]
    if (!step) return
    event.preventDefault()
    const i = Math.max(0, Math.min(CHARACTER_NAMES.length - 1, CHARACTER_NAMES.indexOf(value) + step))
    onChange(CHARACTER_NAMES[i])
    event.currentTarget.querySelectorAll?.('[role=radio]')?.[i]?.focus?.()
  }
  return jsx('div', { className: 'pugin-set__grid', role: 'radiogroup', 'aria-label': 'Character', onKeyDown, children: CHARACTER_NAMES.map(name => jsxs('button', {
    type: 'button', role: 'radio', 'aria-checked': value === name, tabIndex: value === name ? 0 : -1, className: 'pugin-set__tile', 'data-pugin-character': name, title: CHARACTER_LABELS[name] || name, onClick: () => onChange(name),
    children: [jsx('img', { className: 'pugin-set__thumb', src: THUMBS[name], alt: '', draggable: false }, 'img'), jsx('span', { className: 'pugin-set__name', children: (CHARACTER_LABELS[name] || name).replace(' Kitten', '').replace(' Pug', '') }, 'n')]
  }, name)) })
}

export function Settings({ open, onClose, prefs, setPrefs, statusProps }) {
  const update = patch => setPrefs(current => ({ ...current, ...patch }))
  return jsx(Dialog, {
    open, modal: false, onOpenChange: value => { if (!value) onClose() },
    children: open ? jsxs(DialogContent, {
      style: style.dialog, className: `pugin-set${prefs.hidden ? ' pugin-set--off' : ''}`, onInteractOutside: event => event.preventDefault(),
      children: [
        jsx('style', { children: SETTINGS_CSS }, 'css'),
        jsxs('div', { className: 'pugin-set__head', children: [
          jsx(DialogTitle, { className: 'pugin-set__title', children: 'PUGin' }, 't'),
          jsx('span', { className: 'pugin-set__ver', children: `v${VERSION}` }, 'v'),
          jsx('button', { type: 'button', className: 'pugin-set__power', role: 'switch', 'aria-checked': !prefs.hidden, 'aria-label': prefs.hidden ? 'Turn PUGin on' : 'Turn PUGin off', title: prefs.hidden ? 'Turn PUGin on' : 'Turn PUGin off (stops all checks; the plugin stays installed)', 'data-pugin-power': prefs.hidden ? 'off' : 'on', onClick: () => update({ hidden: !prefs.hidden }), children: jsx('svg', { viewBox: '0 0 24 24', width: 16, height: 16, 'aria-hidden': true, children: [jsx('path', { d: 'M12 3v9', fill: 'none', stroke: 'currentColor', strokeWidth: 2.4, strokeLinecap: 'round' }, 'a'), jsx('path', { d: 'M6.3 6.8a8 8 0 1 0 11.4 0', fill: 'none', stroke: 'currentColor', strokeWidth: 2.4, strokeLinecap: 'round' }, 'b')] }) }, 'p')
        ] }, 'head'),
        prefs.hidden ? jsx('div', { className: 'pugin-set__off', children: 'PUGin is off: the companion stays hidden and no checks run. Press the power button to turn it back on.' }, 'off') : null,
        jsx(DialogDescription, { className: 'pugin-set__sub', children: "Dances while this chat works. Click the companion to see what's running." }, 'desc'),
        jsxs('section', { className: 'pugin-set__sec', children: [jsx('span', { className: 'pugin-set__label', children: 'Character' }, 'l'), jsx(CharacterPicker, { value: prefs.character, onChange: character => update({ character }) }, 'p')] }, 'char'),
        jsxs('section', { className: 'pugin-set__sec', children: [
          jsx('span', { className: 'pugin-set__label', children: 'Look' }, 'l'),
          jsx(Slider, { label: 'Size', value: prefs.size, min: SIZE_MIN, max: SIZE_MAX, unit: 'px', onChange: v => update({ size: clampSize(v) }) }, 's'),
          jsx(Slider, { label: 'Opacity', value: clampOpacity(prefs.opacity), min: OPACITY_MIN, max: 100, unit: '%', onChange: v => update({ opacity: clampOpacity(v) }) }, 'o')
        ] }, 'look'),
        jsxs('section', { className: 'pugin-set__sec', children: [
          jsx('span', { className: 'pugin-set__label', children: 'Dance for' }, 'l'),
          jsx(Segmented, { label: 'Dance for', value: prefs.danceScope, options: [['chat-linked', 'Chat + its work'], ['chat', 'Chat only']], onChange: danceScope => update({ danceScope }) }, 'd'),
          jsx('span', { className: 'pugin-set__label', children: 'Visibility' }, 'l2'),
          jsx(Segmented, { label: 'Visibility', value: prefs.presenceMode, options: [['auto-beam', 'Only while working'], ['keep-visible', 'Always']], onChange: presenceMode => update({ presenceMode }) }, 'p'),
          jsx('small', { className: 'pugin-set__hint', children: prefs.danceScope === 'chat-linked' ? 'Working = this chat is replying, or one of its subagents, background processes or Kanban cards is running.' : 'Working = this chat is replying.' }, 'h'),
          jsxs('div', { className: 'pugin-set__row', children: [jsxs('span', { children: ['Nudges', jsx('small', { children: 'NEED YOU!, DONE!, STUCK? callouts' }, 's')] }, 't'), jsx(Switch, { checked: prefs.nudges, onCheckedChange: value => update({ nudges: value === true }), 'aria-label': 'Nudges' }, 'w')] }, 'n'),
          jsxs('div', { className: 'pugin-set__row', children: [jsxs('span', { children: ['Pause motion', jsx('small', { children: 'Stay still instead of dancing' }, 's')] }, 't'), jsx(Switch, { checked: prefs.paused, onCheckedChange: value => update({ paused: value === true }), 'aria-label': 'Pause motion' }, 'w')] }, 'm')
        ] }, 'beh'),
        jsxs('div', { className: 'pugin-set__actions', children: [jsx(Button, { onClick: () => update({ position: null }), children: 'Move above chat bar' }, 'm')] }, 'act'),
        jsx(StatusPanel, statusProps, 'status')
      ]
    }) : null
  })
}

const DISMISSED_KEY = 'pugin.dismissed.v1'

function PluginRoot({ ctx }) {
  const [prefs, setPrefsState] = useState(() => normalizePrefs(ctx.storage?.get?.(PREFS_KEY, DEFAULT_PREFS)))
  const setPrefs = updater => setPrefsState(current => {
    const next = normalizePrefs(typeof updater === 'function' ? updater(current) : updater)
    try { ctx.storage?.set?.(PREFS_KEY, next) } catch {}
    return next
  })
  const [dismissed, setDismissedState] = useState(() => { const raw = ctx.storage?.get?.(DISMISSED_KEY, {}); return isObject(raw) ? raw : {} })
  const setDismissed = next => { setDismissedState(next); try { ctx.storage?.set?.(DISMISSED_KEY, next) } catch {} }
  const [settingsOpen, setSettingsOpen] = useState(false)
  const [receiptOpen, setReceiptOpen] = useState(false)
  const opener = useRef(null)
  const invoker = useRef(null)
  const env = useEnvironment(ctx)

  // ---- activity: the focused chat, its own linked work
  const busy = useValue(host.state.busy) === true
  const runtimeId = useValue(host.state.focusedSessionId)
  const storedId = useValue(host.state.focusedStoredSessionId)
  const owner = useValue(host.state.focusedSessionOwner)
  const ids = { owner: owner || null, runtimeId: runtimeId || null, storedId: storedId || null }
  const [linked, refresh] = useLinkedWork(ctx, ids, !prefs.hidden && prefs.danceScope === 'chat-linked' && env.documentVisible)
  const activity = deriveActivity({ busy, danceScope: prefs.danceScope, linked, ids })
  const settledWorking = useSettled(activity.working, ARRIVE_AFTER_MS, DEPART_AFTER_MS)

  // ---- nudges: needs you / done hand-off / stuck alarm (this chat only)
  const [celebration, setCelebration] = useState(null)
  const [stuck, setStuck] = useState([])
  const previousRef = useRef(null)
  const stuckMemory = useRef(new Map())
  useEffect(() => {
    if (!linked) return undefined
    const finished = diffFinished(previousRef.current, linked)
    previousRef.current = linked
    setStuck(deriveStuck({ linked, ids, memory: stuckMemory.current }))
    // Forget dismissals for cards that are no longer blocked, so a re-block nudges again.
    const blockedIds = new Set((linked.blocked || []).map(item => item.id))
    const kept = Object.fromEntries(Object.entries(dismissed).filter(([id]) => blockedIds.has(id)))
    if (isFresh(linked, ids) && Object.keys(kept).length !== Object.keys(dismissed).length) setDismissed(kept)
    if (finished.length) setCelebration({ text: celebrationText(finished), at: Date.now() })
  }, [linked]) // eslint-disable-line react-hooks/exhaustive-deps
  // The celebration owns its own timer, so the 4 s poll can't keep restarting (or cancelling) it.
  useEffect(() => {
    if (!celebration) return undefined
    const timer = setTimeout(() => setCelebration(null), Math.max(0, CELEBRATE_MS - (Date.now() - celebration.at)))
    return () => clearTimeout(timer)
  }, [celebration])
  const needs = deriveNeeds({ linked, ids, dismissed })
  const mood = prefs.nudges && prefs.danceScope === 'chat-linked' ? deriveMood({ needs, celebration: celebration?.text || null, stuck }) : null

  // ---- presence
  const motionOff = prefs.paused || env.reducedMotion || !env.documentVisible
  const motionReason = prefs.paused ? 'Motion paused' : env.reducedMotion ? 'Reduced motion is on' : !env.documentVisible ? 'Window hidden' : null
  const [phase, setPhase] = useState('absent')
  const [preview, setPreview] = useState(null)
  const previewing = settingsOpen && !prefs.hidden
  const wantPresent = preview ? preview === 'arriving' : (previewing || (receiptOpen && !prefs.hidden) || targetPresence({ prefs, settledWorking, mood }))
  useEffect(() => { setPhase(current => nextPhase(current, { targetPresent: wantPresent, motionOff })) }, [wantPresent, motionOff, phase])
  const onBeamDone = () => { setPhase(current => finishEffect(current)); setPreview(null) }
  const dancing = phase === 'present' && !motionOff && mood?.kind !== 'needs' && (settledWorking || previewing || mood?.kind === 'done')

  // ---- position (settings never touch it; resize only clamps the display)
  const [dragPos, setDragPos] = useState(null)
  const dragRef = useRef(null)
  const draggedRef = useRef(false)
  const composer = useComposerRect()
  const saved = clampPosition(prefs.position, prefs.size, env.viewport, composer)
  const position = dragPos || saved
  const drag = {
    begin: (x, y) => { draggedRef.current = false; dragRef.current = { dx: x - saved.x, dy: y - saved.y, x0: x, y0: y, moved: false } },
    move: (x, y) => { const d = dragRef.current; if (!d) return; if (!d.moved && Math.hypot(x - d.x0, y - d.y0) < 4) return; d.moved = true; setDragPos(clampPosition({ x: x - d.dx, y: y - d.dy }, prefs.size, env.viewport)) },
    end: () => { const d = dragRef.current; dragRef.current = null; draggedRef.current = Boolean(d?.moved); if (d?.moved && dragPos) setPrefs(c => ({ ...c, position: dragPos })); setDragPos(null) },
    cancel: () => { dragRef.current = null; setDragPos(null) },
    nudge: (dx, dy, big) => { const step = big ? 24 : 4; setPrefs(c => ({ ...c, position: clampPosition({ x: saved.x + dx * step, y: saved.y + dy * step }, c.size, env.viewport) })) }
  }
  const onTap = () => { if (draggedRef.current) { draggedRef.current = false; return } setReceiptFocus(null); setReceiptOpen(open => !open) }

  const openSettings = source => { invoker.current = source || opener.current; setReceiptOpen(false); setSettingsOpen(true) }
  const closeSettings = () => { setSettingsOpen(false); queueMicrotask(() => invoker.current?.focus?.()) }
  const onStop = async item => { const result = await stopItem(host, ids, item); refresh(); return result }
  const [receiptFocus, setReceiptFocus] = useState(null)
  const onOpenKanban = async item => {
    setReceiptOpen(false)
    let copied = false
    try { copied = Boolean(await ctx.os?.writeClipboard?.(item.id)) } catch {}
    try { host.navigate?.('/kanban') } catch {}
    try { host.notify?.({ kind: 'info', title: 'PUGin', message: `${item.label}${item.board ? ` — board: ${item.board}` : ''}`, detail: copied ? 'Card ID copied — paste it into the Kanban search box (switch to that board first if needed).' : `Look for card ${item.id}.`, durationMs: 9000 }) } catch {}
  }
  const onAnswer = () => { setReceiptOpen(false); try { host.composer?.focus?.(null) } catch {} }
  const onCallout = target => {
    const action = calloutAction(target)
    if (action.kind === 'composer') onAnswer()
    else if (action.kind === 'kanban') onOpenKanban(target)
    else { setReceiptFocus(action.focus || null); setReceiptOpen(true) }
  }
  const onDismiss = id => setDismissed({ ...dismissed, [id]: true })
  const statusLabel = prefs.hidden ? 'PUGin (off)' : needs.length && prefs.nudges ? 'PUGin ✋' : activity.working ? 'PUGin •' : 'PUGin'

  return jsxs('div', {
    'data-pugin-root': true,
    children: [
      jsx('style', { children: beamCss + pugCss }),
      jsx('button', { ref: opener, type: 'button', 'data-pugin-statusbar': true, 'aria-haspopup': 'dialog', 'aria-expanded': settingsOpen, onClick: () => settingsOpen ? closeSettings() : openSettings(opener.current), title: mood ? mood.text : activity.working ? activity.reasons.map(r => r.label).join('\n') : 'PUGin is idle', children: statusLabel }),
      jsx(Companion, { phase, prefs, position, dancing, mood, motionOff, onBeamDone, onOpenSettings: openSettings, onTap, onCallout, drag, settingsOpen, showBubble: !receiptOpen && !settingsOpen }),
      jsx(Receipt, { open: receiptOpen && phase !== 'absent', onClose: () => setReceiptOpen(false), anchor: position, size: prefs.size, viewport: env.viewport, busy, linked: linked || emptyLinked(''), fresh: isFresh(linked, ids), needs, stuck, onStop, onOpenKanban, onAnswer, onDismiss, focus: receiptFocus }),
      jsx(Settings, { open: settingsOpen, onClose: closeSettings, prefs, setPrefs, statusProps: { activity, linked, prefs, phase, busy, needs, stuck, motionReason: previewing && !settledWorking ? 'Previewing while settings are open' : motionReason } })
    ]
  })
}

export default {
  id: PLUGIN_ID,
  name: PLUGIN_NAME,
  version: VERSION,
  description: "A dancing companion for the chat you are viewing: it follows that chat's subagents, processes and Kanban cards, nudges you when something needs you, celebrates finished work and flags stuck work.",
  register(ctx) {
    ctx.register({ id: PLUGIN_ID, area: STATUSBAR_AREAS.left, order: 40, render: () => jsx(PluginRoot, { ctx }) })
    ctx.register({ id: `${PLUGIN_ID}-chat-bar-anchor`, area: COMPOSER_AREAS.top, order: 999, render: () => jsx(ComposerAnchor, {}) })
  }
}
